import {BELL_NOTES,BELL_MODEL,bellNoteById} from './bell-studio-content.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function bellNoteArt(id){const n=bellNoteById(id);if(!n)return '';const shapes={low:'<circle cx="32" cy="39" r="13" fill="#729faf"/>',middle:'<path d="M32 14l15 15-15 15-15-15Z" fill="#b69b58"/>',high:'<path d="M32 5l15 27H17Z" fill="#b5829e"/>',rest:'<path d="M24 17v28m16-28v28" stroke="#729584" stroke-width="7"/>'};return `<svg class="bs-note-art" viewBox="0 0 64 58" aria-hidden="true">${shapes[id]}<path d="M10 53H54" stroke="#183f39" stroke-width="1"/></svg>`;}
export function bellSignalArt(){return `<figure class="bs-signals"><figcaption><strong>Faster repeated changes, higher pitch</strong><p>${esc(BELL_MODEL.diagramNotice)}</p></figcaption>${BELL_NOTES.filter(n=>n.frequency!==null).map(n=>{const points=Array.from({length:129},(_,i)=>`${25+i*350/128},${50-18*Math.sin(i/128*n.cycles*2*Math.PI)}`).join(' ');return `<div><strong>${n.name} · ${n.frequency} Hz</strong><svg viewBox="0 0 400 88" role="img" aria-label="${n.name}: ${n.cycles} repeated cycles in the same short time window. Equal vertical signal height."><path d="M25 50H375" stroke="#b7c9ad"/><polyline points="${points}" fill="none" stroke="#397958" stroke-width="2.5"/><path d="M25 75H375M25 70V80M375 70V80" stroke="#183f39"/><text x="200" y="87" text-anchor="middle" font-size="13" fill="#183f39">same short time</text></svg></div>`;}).join('')}<p class="tiny">The signal setting stays the same size. Higher pitch does not mean louder. This is not an air-particle path.</p></figure>`;}
export function bellSequenceArt(sequence,{label='Call sequence'}={}){return `<div class="bs-picture-call" role="img" aria-label="${esc(label)}: ${sequence.length?sequence.map(id=>bellNoteById(id)?.name||'unknown').join(', '):'empty draft'}">${sequence.length?sequence.map((id,i)=>`<span class="bs-picture-slot"><small>${i+1}</small>${bellNoteArt(id)}<span>${esc(bellNoteById(id)?.name)}</span></span>`).join(''):'<span class="bs-empty">An open place for your first tone.</span>'}</div>`;}
